tape( 'the function throws if provided an invalid `state` option (incompatible schema version)', function test( t ) {
	var state;
	t.throws( badValue, RangeError, 'throws a RangeError' );
	t.end();

	function badValue() {
		var prng = factory();
		state = prng.state;
		state[ 0 ] = 999; // corrupt schema version
		factory({
			'state': state
		});
	}
});

