tape( 'the returned function returns pseudorandom unsigned 32-bit integers on the interval [1, 2^32-1]', function test( t ) {
	var xorshift32;
	var v;
	var i;

	xorshift32 = factory();
	for ( i = 0; i < 1e3; i++ ) {
		v = xorshift32();
		t.strictEqual( typeof v, 'number', 'returns expected value' );
		t.strictEqual( isNonNegativeInteger( v ), true, 'returns a non-negative integer' );
		t.strictEqual( v >= 1 && v <= UINT32_MAX, true, 'returns an integer between 1 and 2^32-1 (inclusive)' );
	}
	t.end();
});

tape( 'the returned function never returns zero', function test( t ) {
	var xorshift32;
	var i;

	xorshift32 = factory();
	for ( i = 0; i < 1e3; i++ ) {
		t.notEqual( xorshift32(), 0, 'does not return zero' );
	}
	t.end();
});

tape( 'the `normalized` method returns pseudorandom numbers on the interval (0, 1]', function test( t ) {
	var xorshift32;
	var v;
	var i;

	xorshift32 = factory();
	for ( i = 0; i < 1e3; i++ ) {
		v = xorshift32.normalized();
		t.strictEqual( typeof v, 'number', 'returns expected value' );
		t.strictEqual( v > 0.0 && v <= 1.0, true, 'returns a number strictly between 0 (exclusive) and 1 (inclusive)' );
	}
	t.end();
});

tape( 'two PRNGs with the same seed produce the same output sequence', function test( t ) {
	var xorshift32a;
	var xorshift32b;
	var i;

	xorshift32a = factory({
		'seed': 42
	});
	xorshift32b = factory({
		'seed': 42
	});

	for ( i = 0; i < 1e3; i++ ) {
		t.strictEqual( xorshift32a(), xorshift32b(), 'both return the same value. i: '+i+'.' );
	}
	t.end();
});

tape( 'two PRNGs with the same seed produce the same normalized output sequence', function test( t ) {
	var xorshift32a;
	var xorshift32b;
	var i;

	xorshift32a = factory({
		'seed': 42
	});
	xorshift32b = factory({
		'seed': 42
	});

	for ( i = 0; i < 1e3; i++ ) {
		t.strictEqual( xorshift32a.normalized(), xorshift32b.normalized(), 'both return the same value. i: '+i+'.' );
	}
	t.end();
});

tape( 'two PRNGs with different seeds produce different output sequences', function test( t ) {
	var xorshift32a;
	var xorshift32b;
	var diff;
	var i;

	xorshift32a = factory({
		'seed': 1
	});
	xorshift32b = factory({
		'seed': 2
	});

	diff = false;
	for ( i = 0; i < 1e2; i++ ) {
		if ( xorshift32a() !== xorshift32b() ) {
			diff = true;
			break;
		}
	}
	t.strictEqual( diff, true, 'generators with different seeds produce different sequences' );
	t.end();
});

tape( 'the returned function supports setting the generator state', function test( t ) {
	var xorshift32;
	var state;
	var arr;
	var i;

	xorshift32 = factory();

	// Move to a future state...
	for ( i = 0; i < 100; i++ ) {
		xorshift32();
	}
	// Capture the current state:
	state = xorshift32.state;

	// Move to a future state...
	arr = [];
	for ( i = 0; i < 100; i++ ) {
		arr.push( xorshift32() );
	}
	// Set the state:
	xorshift32.state = state;

	// Replay previously generated values...
	for ( i = 0; i < 100; i++ ) {
		t.strictEqual( xorshift32(), arr[ i ], 'returns expected value. i: '+i+'.' );
	}
	t.end();
});

