tape( 'the function supports providing a state from a separate generator instance (copy: true)', function test( t ) {
	var xorshift32a;
	var xorshift32b;
	var state;
	var arr;
	var i;

	xorshift32a = factory();

	// Move to a future state...
	for ( i = 0; i < 100; i++ ) {
		xorshift32a();
	}
	// Capture the current state:
	state = xorshift32a.state;

	// Create a new PRNG from the captured state:
	xorshift32b = factory({
		'state': state
	});

	// Generate values from both PRNGs; they should agree:
	arr = [];
	for ( i = 0; i < 100; i++ ) {
		arr.push( xorshift32a() );
	}
	for ( i = 0; i < 100; i++ ) {
		t.strictEqual( xorshift32b(), arr[ i ], 'returns expected value. i: '+i+'.' );
	}
	t.end();
});

tape( 'the function supports providing a state from a separate generator instance (copy: false)', function test( t ) {
	var xorshift32a;
	var xorshift32b;
	var state;
	var arr;
	var i;

	xorshift32a = factory();

	// Move to a future state...
	for ( i = 0; i < 100; i++ ) {
		xorshift32a();
	}
	// Capture the current state:
	state = xorshift32a.state;

	// Create a new PRNG from the captured state (shared, not copied):
	xorshift32b = factory({
		'state': state,
		'copy': false
	});

	// Generate values from both PRNGs; they should agree:
	arr = [];
	for ( i = 0; i < 100; i++ ) {
		arr.push( xorshift32a() );
	}
	for ( i = 0; i < 100; i++ ) {
		t.strictEqual( xorshift32b(), arr[ i ], 'returns expected value. i: '+i+'.' );
	}
	t.end();
});

