tape( 'the `setState` accessor throws if provided an argument which is not a Uint32Array', function test( t ) {
	var xorshift32;
	var values;
	var i;

	xorshift32 = factory();

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[],
		new Int32Array( 10 ),
		function noop() {}
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws a TypeError when provided '+values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			xorshift32.state = value;
		};
	}
});

tape( 'the `setState` accessor throws if provided an invalid state array', function test( t ) {
	var xorshift32 = factory();

	t.throws( badValue, RangeError, 'throws a RangeError' );
	t.end();

	function badValue() {
		xorshift32.state = new Uint32Array( 2 ); // too short
	}
});

tape( 'the `toJSON` method returns an object with expected properties', function test( t ) {
	var xorshift32;
	var o;

	xorshift32 = factory({
		'seed': 12345
	});
	o = xorshift32.toJSON();

	t.strictEqual( typeof o, 'object', 'returns an object' );
	t.strictEqual( o.type, 'PRNG', 'has expected type property' );
	t.strictEqual( o.name, 'xorshift32', 'has expected name property' );
	t.strictEqual( typeof o.state, 'object', 'has expected state property' );
	t.ok( Array.isArray( o.params ), 'has expected params property' );
	t.end();
});

tape( 'a zero seed is replaced with 1 to avoid the degenerate all-zeros fixed point', function test( t ) {
	var xorshift32;
	var v;
	var i;

	xorshift32 = factory({
		'seed': 0
	});

	for ( i = 0; i < 1e3; i++ ) {
		v = xorshift32();
		t.notEqual( v, 0, 'does not return zero' );
	}
	t.end();
});
